function main(req) {
  const body = jsonParse(req.body, {});
  const action = body.action || 'list';

  const db = [
    { id: 1, name: 'Alice', role: 'admin' },
    { id: 2, name: 'Bob', role: 'user' },
    { id: 3, name: 'Charlie', role: 'user' }
  ];

  switch (action) {
    case 'list':
      return { users: db, total: db.length };

    case 'get': {
      const user = db.find(u => u.id === body.id);
      if (!user) return { error: 'user not found' };
      return { user };
    }

    case 'search': {
      const q = (body.query || '').toLowerCase();
      const results = db.filter(u => u.name.toLowerCase().includes(q));
      return { results, count: results.length };
    }

    default:
      return { error: 'unknown action', available: ['list', 'get', 'search'] };
  }
}
